import{_ as r,a as t,b as o,c as i,d as l,e as n,f as h,g as s}from"./chunks/994939c245a2d9ad6668.DCbw-DcX.js";import{_ as m,C as c,o as d,c as u,j as e,a as b,E as f,a6 as _}from"./chunks/framework.CnPv4DE1.js";const D=JSON.parse('{"title":"阅读：用一个简单的习惯改变你的生活","description":"","frontmatter":{"title":"阅读：用一个简单的习惯改变你的生活","originalTitle":"Reading: Change Your Life With One Simple Habit","date":"2024-07-27","originalUrl":"https://thedankoe.com/letters/reading-change-your-life-with-one-simple-habit/","minutes":23,"sourceHash":"ffd53204595858b55f6942b3383afc39d3d0f761eefe653d94279da3d7df2e45","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/reading-change-your-life-with-one-simple-habit/"}]]},"headers":[],"relativePath":"letters/reading-change-your-life-with-one-simple-habit.md","filePath":"letters/reading-change-your-life-with-one-simple-habit.md"}'),g={name:"letters/reading-change-your-life-with-one-simple-habit.md"};function k(q,p,x,P,T,w){const a=c("ArticleMeta");return d(),u("div",null,[p[0]||(p[0]=e("h1",{id:"阅读-用一个简单的习惯改变你的生活",tabindex:"-1"},[b("阅读：用一个简单的习惯改变你的生活 "),e("a",{class:"header-anchor",href:"#阅读-用一个简单的习惯改变你的生活","aria-label":'Permalink to "阅读：用一个简单的习惯改变你的生活"'},"​")],-1)),f(a),p[1]||(p[1]=_('<p><a href="https://www.youtube.com/embed/jNUFWPqz3Wk?si=Xid7L7gm5i14UDAr" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>你能处在的最糟糕的境地，就是卡在跌入谷底的<em>前一刻</em>。</p><p>痛苦不足以让你做出改变。</p><p><em>刚好舒服到让你安于现状。</em></p><p>我很庆幸我在大学一年级的那个夏天被捕了。</p><p>你问发生了什么？</p><p>我室友的女朋友为了另一个男人离开了他，之后他感觉很糟。他需要放松一下。为此能找到的第一个选项，你猜对了，就是大麻。</p><p>我、我室友，还有另外两个朋友坐在街对面停车库里我的车上。我们有说有笑，直到其中一个朋友看了眼后视镜……“伙计们，我们后面有个骑自行车的警察。”</p><p>“这可不好笑，老兄，”我回答道，尽量不让自己抓狂，但当我亲眼看过去时，发现他没撒谎。</p><p>既然这跟阅读毫无关系，我们直接说重点。</p><p>我和我室友被捕了。</p><p>我们被登记在案，被盘问是谁把毒品卖给我们的，然后那天晚上就被遣送回家了。</p><p>第二天早上，我没把这事放在心上。</p><p>但几个月后，在2016年，当我回到家做救生员的暑期工作时，我在信箱里发现了一封信。</p><p>上面印有政府的印章。</p><p>还没等我来得及思考，我的心就沉到了谷底。</p><p>我父母还没回家，所以我跑进屋把它拆开。</p><p>我面临两个选择：</p><p>上法庭，并且很可能因为在大学校园里吸食违禁毒品而成为一名被定罪的重罪犯；或者参加一个毒品转移改造项目，在那里我每周都会在随机的一天接受检测。哦，还有，这个项目要花几千块钱，作为一个穷得叮当响的大学生，我根本拿不出这笔钱。</p><p>我的大脑瞬间崩溃了。</p><p>每一个糟糕的结果都像放映机里的胶片一样在我的脑海中滚动。</p><p>我不知道该怎么办。我不能告诉我父母。我没有钱。我<em>绝对不能</em>成为重罪犯……我的人生才刚刚开始。所有这一切就因为我和朋友们抽了口烟、开了个玩笑？？真的假的？！</p><p>担忧变成了愤怒。愤怒变成了挫败。</p><p>然后……<em>我产生了一个想法</em>。</p><p>我当时很迷健身，我想起了一个我很喜欢向其学习的YouTube博主（YouTuber）推荐的一本书。</p><p>书名叫《当下的力量》（The Power of Now）。</p><h3 id="学校让你讨厌这个能改变人生的习惯" tabindex="-1">学校让你讨厌这个能改变人生的习惯 <a class="header-anchor" href="#学校让你讨厌这个能改变人生的习惯" aria-label="Permalink to &quot;学校让你讨厌这个能改变人生的习惯&quot;">​</a></h3><p>灵性？那是给嬉皮士准备的。</p><p>但我走投无路了。</p><p>我愿意做任何事来帮助我的头脑应对这个局面。</p><p>所以，每天早上，我会坐在我爸的门廊上读一个小时的书，手里端着一杯黑咖啡（就是装在大蓝色罐子里的那种，尝起来就像是从加油站放了一个星期的咖啡机里倒出来的）。</p><p><em>书中的道理犹如当头棒喝。</em></p><p>震撼到我不禁去想象，因为在公立学校毕业后不再阅读，我的人生到底错失了多少知识。那些本可以给我提供过上更好生活之工具的知识。</p><p>有趣的是，如果我没有跌入谷底，我的大脑就会排斥书中那些反常的观点。</p><p>而很酷的是，你不需要非得跌入谷底才能体验到同样的效果。</p><p>我上一批真正<em>主动选择</em>去读的书，还是《神奇树屋》（The Magic Treehouse）和《少年间谍艾列克》（Alex Rider）系列。但那已经是十多年前的事了。从那以后，我开始讨厌阅读。</p><p>在高中时，我被迫去读那些我根本不关心、也没有任何兴趣的书。</p><p>在发现了正念和临在之后，我的生活改变了。我变得更快乐、更平静，而且那个糟糕的处境似乎并没有影响到我。我见招拆招地处理了它。生活很美好。至少有时候是。</p><p>它也让我很快认识到了灵性地位的陷阱。我经常会因为父母“不懂”而对他们发脾气。</p><p>“说真的老爸，难道你不想结束你的痛苦，像<em>我</em>一样开悟吗？”</p><p>哈哈。</p><p>关于灵性，有很多我能分享的经验，但那不是这封信的主题。</p><p>学校可能让你讨厌阅读。</p><p>从而，它们让你讨厌学习。</p><p>如果你讨厌学习，可以毫不夸张地说，你已经失去了很多对生活的热情。学习是人类基本的一种驱动力。</p><p>没有它，日常活动就不再那么令人愉悦。</p><p>交流也不再那么有意义。</p><p>你的日子感觉重复且死气沉沉。</p><p>你看不到你的未来会和现在有什么大的不同。</p><p>但如果我告诉你，有一个能改变人生的习惯就隐藏在你的眼皮底下呢？</p><p>问题在于，大多数人仍然是学校系统的克隆体。他们走在一条并非自己设定的人生轨迹上。</p><p>如果你想要创造一份充满成就感的事业、拥有更好的人际关系、变得更聪明、重新发现生活的深度，并且在这个忙碌且充满分心的世界里慢下来……</p><p>阅读吧。</p><h2 id="第一部分-阅读的理由" tabindex="-1">第一部分）阅读的理由 <a class="header-anchor" href="#第一部分-阅读的理由" aria-label="Permalink to &quot;第一部分）阅读的理由&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>你不需要为了阅读找理由。</p><p>你不需要为了改善生活找理由。</p><p>你不需要为了在这个世界上过得专注、充实且头脑清醒而找理由。</p><p>但是，众所周知，那并非现代世界的现实。</p><p>让我们从这样一个事实开始：大多数人并没有意识到他们错过了什么。现在，跟紧我的思路，因为接下来可能会变得有些抽象，但如果你理解了其中的道理，它们的影响将是深远的。</p><h3 id="_1-冰箱里有什么-你才能做什么菜。" tabindex="-1">1) 冰箱里有什么，你才能做什么菜。 <a class="header-anchor" href="#_1-冰箱里有什么-你才能做什么菜。" aria-label="Permalink to &quot;1) 冰箱里有什么，你才能做什么菜。&quot;">​</a></h3><p>这是蒂姆·德莫斯（Tim Demoss）在他的“阅读的理由”<a href="https://youtube.com/playlist?list=PLZpKwDwO5HwPrGyF9_Py_-BHcxbp_Co2c&amp;si=1UCI_3NDFTkDlw5W" target="_blank" rel="noreferrer">系列视频</a>中的一个观点。我最近一直在疯狂刷他的视频，因为他提供了很棒的观点（也是为了给自己编程，让自己多读书）。</p><p>如果你没有那些能够<em>打开心智并拓展认知</em>的目标，你的大脑就不会注意到那些能够改变人生的新机遇。</p><p>如果你身边都是那些想要获得某些证书（比如大学学位）以求得一份高薪工作的人，你的大脑只会注意到那些能帮助你实现那个目标的信息和想法。</p><p>但如果你有意识地用新书来重新教育自己，你就会接触到新颖的观点，从而让你能够为自己确立新的目标。</p><p>你的认知表面积随之扩大。</p><p>你开始把生活中的新想法联系起来。</p><p>你会注意到一个机会——一个你以前绝不会关心或注意到的机会——它会激励你去做一些<em>全新的、未知的</em>事情。终于开始做那个你一直推迟的生意，就是一个很好的例子。</p><p>然后，也只有在那个时候，你的大脑才会开始注意到更高层次的想法，让你能在这个领域看到进展。你会开始在社交媒体上注意到初级、中级和高级的策略，算法会改变并展示给你更多相关内容，而你也在慢慢地对你的大脑进行重新编程，以实现人生中更好的目标。这种效应发生的领域远不止于你在社交媒体上消费的内容。</p><p><em>你的目标已经发生了根本性的改变。</em></p><p>你和朋友的对话开始发生转变。你的搜索记录从那些你可能不该搜索的东西，变成了像“2024年最佳商业模式”这样的内容。然后，你尝到了生活可能变成什么样的甜头。你可能会在第一次尝试时失败，第二次也会，因为事情就是这样……但你的潜力将一直存在。即使你放弃了，它也会不断地在心里挠你。你再也回不去了。</p><p>重点是：</p><p>生活很可能与你擦肩而过，因为你日复一日接触到的都是同样的信息。自从你实现了社会为你设定的那些目标后，你的生活就再也没怎么变过。</p><p>你只能用冰箱里现有的食材做饭。如果你的冰箱不扩容，你每天都会吃同样无聊的一餐（这并不总是一件坏事，比如在减肥时，但如果你的冰箱里装满了垃圾食品，那就是件非常糟糕的事了）。</p><p>你需要一个新目标。</p><p>你需要为了实现那个目标而进行自我教育。</p><p>单单这一个简单的过程，就将成为你生活中许多乐趣的源泉。</p><p>真正的教育关乎好奇心和探索，而不是死记硬背和墨守成规。</p><p>顺便说一句，这就是我们打造 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 的原因。为了帮助你拥有一个“第二大脑”，或者说一个能让写作变得无缝衔接的想法数据库。你的“第二大脑”就是你在冰箱里用来做饭的食材，哈哈。软启动日期是九月中旬 🙂（除非你想获得<a href="https://cc.kortex.co/" target="_blank" rel="noreferrer">终身访问权限</a>）。</p><h3 id="_2-大脑是一块必须经过训练的肌肉。" tabindex="-1">2) 大脑是一块必须经过训练的肌肉。 <a class="header-anchor" href="#_2-大脑是一块必须经过训练的肌肉。" aria-label="Permalink to &quot;2) 大脑是一块必须经过训练的肌肉。&quot;">​</a></h3><p>许多人痴迷于身体健康，却很少关心心理健康。</p><p>好吧……他们确实关心心理健康，但却用创可贴式的治标方法来解决他们意识里的紊乱。</p><p>心理健康关乎意义构建、理解和清醒。焦虑和抑郁，即使它们源于化学物质失衡（我不是说这能治愈它），也是一个狭隘的头脑专注于熟悉的过去或可预测的（通常是负面的）未来所产生的产物。</p><p>当你感到迷茫时，通常是因为你处于一个混乱的生活境遇中，而你缺乏理解它所需的知识或技能。你看不到出路。</p><p>你没有处在你想去的地方，是因为你举不起那些能让你到达那里的心智重物。</p><p>你不具备让你在生活中处于那个位置的知识或技能。</p><p>大脑是现实的操作系统，而大多数人运行的还是 Windows 98。许多其他人则退化成了一个寻呼机，每当他们需要对某些挑战了其软件里政府官方言论设定的事情做出负面反应时，它就会滴滴作响。</p><p>你要通过重新对你的大脑进行编程来改变你的生活。</p><p>多读些能挑战你信念的书，让你看清自己到底有多少盲区，并鼓励你以一种有益于你自己和他人生活的方式去改变你的行为。</p><p>别指望第一次尝试就能完成一次315磅的心智卧推。</p><p>遇到不理解的观点就先跳过。随着你继续保持阅读习惯，你的大脑会慢慢把这些点连接起来。</p><h3 id="_3-终结坏习惯最好的方法是替换它们。" tabindex="-1">3) 终结坏习惯最好的方法是替换它们。 <a class="header-anchor" href="#_3-终结坏习惯最好的方法是替换它们。" aria-label="Permalink to &quot;3) 终结坏习惯最好的方法是替换它们。&quot;">​</a></h3><p>你一天中能拥有的习惯就只有那么多。</p><p>一个给你的大脑，一个给你的身体，一个给你的工作，一个给你的感情关系。这是最低配置。</p><p>如果你现在停下来审查你的一天，你在无意识中执行的习惯里，有多少是真的在帮助你的未来的？</p><p>当我们观察社会时，很容易推断出这个数字接近于零。由此，我们更容易推断出（1）他们不快乐，而且（2）20年后，他们还会是同一个人，身处同一个位置，带着同一种思维。</p><p>大家都知道，晚上死盯着电视机，沉浸在那种不自然的人造蓝光中——如果你一整天都没晒过太阳的话，这很可能还会增加患皮肤癌的风险——绝对不是什么好事。</p><p>在这种情况下，把那个坏习惯换成阅读，能够极大地改变的不仅仅是你的心理健康。它甚至有可能救你一命。</p><p>坏习惯之所以坏，不仅是因为它们占用了你培养好习惯的时间；它们还在慢慢侵蚀你生活的每一个其他层面。坏习惯的影响不是中性的。它们带来的恶果是呈指数级增长的。同样，好习惯一旦持之以恒，其带来的好处也是指数级的。</p><p>正如人们常说的，“每天进步1%”。</p><p><img src="'+o+'" alt=""></p><p>那么现在的问题是：</p><p>我该读什么，才能让我想要养成这个习惯？</p><p>我该如何阅读，才能从这个习惯中获得最大的收益？</p><p>我可以使用哪些策略让这种习惯的改变变得有趣？</p><h2 id="第二部分-读些什么" tabindex="-1">第二部分）读些什么 <a class="header-anchor" href="#第二部分-读些什么" aria-label="Permalink to &quot;第二部分）读些什么&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>你是否曾经思考过 <em>intention</em>（意图）这个词的含义？</p><p>如果你把它作为生活的基本运行原则，它会非常强大。</p><p><strong>在拉丁语中，<em>intentio</em>（意图）的意思是拉紧、延伸或伸展。</strong></p><p>因此，要想过一种有意图的生活，<em>你在向什么方向伸展？你在为何而奋斗？</em></p><p>就像肌肉被拉伸和锻炼以增强肌肉量、耐力和力量一样，带着意图去生活，就是通过简单地参与生活来锻炼心智的肌肉。正因为如此，生活变得更加有意义。</p><p>当你向着自己选择的目标伸展时，你的大脑会需要营养来为这种成长提供动力。</p><p>那时，且只有那时，书本才能帮到你。</p><p>如果你的生活没有在做任何打破常规的事情，阅读对你的帮助不大。至少，改变生活的意图<em>必须</em>存在。<em>意图标志着你的大脑已经准备好去接收，而不是仅仅做出被动反应。</em></p><p>为什么这是必须的？</p><p>因为每个人对一本书的解读都不一样。</p><p>一个人带着成为更优秀的CEO的目标去读哲学，那些观点就会适用于他的事业。</p><p>另一个人可能想要改善人际关系，读同一本书，并能在那个领域看到进步。</p><p>这样一来，任何书籍、对话、文章或信息都能帮助你实现目标。你<em>没必要</em>限制自己的阅读范围，但比起随机瞎选，总有某些类型的书能给你带来多得多的帮助。</p><h3 id="_1-阅读有挑战性的书。" tabindex="-1">1) 阅读有挑战性的书。 <a class="header-anchor" href="#_1-阅读有挑战性的书。" aria-label="Permalink to &quot;1) 阅读有挑战性的书。&quot;">​</a></h3><p>一本有挑战性的书，是潜入未知领域的完美隐喻。</p><p>你不知道会发生什么。</p><p>你很难弄懂其中的一切。</p><p>但你只能一步一步、一页一页地慢慢来。</p><p>事情开始变得合理了。感觉很棒。你建立起了联想，多巴胺涌入大脑，进步正在发生。很快，你就爱不释手了。那些想法足以改变生活。你的大脑充满了潜能。</p><p><em>我应该开始做那个生意了……</em></p><p><em>我应该去学那项技能……</em></p><p><em>我现在不该分心，我得去散散步……</em></p><p>一本有挑战性的书教会你的，不仅仅是书里的观点。它还教会了你人生中最重要的过程之一：进步。</p><p>你开始明白进步不是线性的。刚开始什么也没发生，然后一切都水到渠成了。前一秒，你还迷失在黑暗中。张力不断积聚，直到恒星爆炸，产生散布在整个银河系的原子核。你沿途点亮的所有小蜡烛开始照亮整个房间，让你能够清晰而专注地看清那个新的人生领域。</p><p>一本有挑战性的书并不总是让人一看就懂。</p><p>它会让你感到不知所措。</p><p>当这种感觉出现时，不要急着把它贴上坏的标签。</p><p>你本来就该感到不知所措。</p><p>要意识到，困惑和不知所措意味着你的大脑正在寻找答案并努力学习。不要停下来。</p><h3 id="_2-读你喜欢的-直到你喜欢上阅读。——纳瓦尔-naval" tabindex="-1">2) 读你喜欢的，直到你喜欢上阅读。——纳瓦尔 (Naval) <a class="header-anchor" href="#_2-读你喜欢的-直到你喜欢上阅读。——纳瓦尔-naval" aria-label="Permalink to &quot;2) 读你喜欢的，直到你喜欢上阅读。——纳瓦尔 (Naval)&quot;">​</a></h3><p>习惯养成的原则不仅仅适用于读书。</p><p>当你刚开始去健身房时，盲目地走进去，在不同的器械间随机乱跳，还指望自己能享受这个过程，那简直太蠢了。</p><p>首先，你会去研究那些与你生活目标相匹配的训练计划。</p><p>如果你是个大忙人，一个为期6天的大容量健美分化训练可能不会让你觉得享受。但一个3天的极简训练计划可能就恰到好处。有人会反驳说这并不是肌肉生长的最佳选择，但你的目标不仅仅是长肌肉。你选择的是最适合你自己目标的计划，而不是别人的目标。</p><p>在那之后，完全照搬计划也许管用，但你可能会讨厌某些动作，以至于想跳过练腿日（举个常见的例子哈哈）。</p><p>这就是你的机会，去研究有哪些新的动作可以替换，同时还能保留计划本身的效果。</p><p>现在，作为一个健身房的新手，你清楚地知道到了那儿该做什么（达成第1点：享受和心流），你有了<em>你</em>期待去做的训练动作（达成第2点），因为这两点，你会比用其他任何方式看到更多的进步，并对这个过程上瘾（达成第3点）。你有清晰的方向。你有专注力。你的心思不会分散去想别人怎么看你。焦虑感消散了。</p><p>对于你读的书和你阅读的方式，道理也是一样的。</p><p>就像思维健身房里的训练一样，选择那些<em>真正</em>让你感兴趣的书。</p><p>然后，一旦这成为了你生活中的一个基础习惯，你自然就会知道该读什么了。</p><p><em>有效的习惯养成，是通过自我实验来找到“有用”和“你喜欢”的交集。</em></p><h3 id="_3-阅读能让你变得聪明的书。" tabindex="-1">3) 阅读能让你变得聪明的书。 <a class="header-anchor" href="#_3-阅读能让你变得聪明的书。" aria-label="Permalink to &quot;3) 阅读能让你变得聪明的书。&quot;">​</a></h3><p>什么是聪明（智慧）？</p><p>聪明不在于你知道多少，而在于你理解多少。</p><p>既然我好像就是忍不住要引用纳瓦尔的话，那再来一句：</p><blockquote><p>如果你理解了，你就不需要死记硬背。</p><p>如果你不理解，你也不会想去死记硬背。</p></blockquote><p><em>绝了。</em></p><p>聪明是整体性的。</p><p>当我们说某人非常聪明时，我们的意思是他们具备更高的整体模式识别能力。</p><p>他们能把各个点连接起来，以此来理解这个世界。</p><p>他们有一种深刻的洞察力，能将其转化为直觉，从而使他们能做出明智的决定。</p><p>就这一点而言，聪明并不是“书呆子式的聪明（book smarts）”。死读书往往被用作一种伪装，用来过度分析风险，使人变得目光短浅，看不到风险背后的东西，最终导致无所作为和随波逐流。那不是聪明。</p><p>聪明不是被困在局部，而是在整体中遨游。</p><p>研究过流行商业策略的人可能会在执行该策略时很有效率，但如果一个人对商业整体大局有深刻理解，就能创造出自己的策略，并无论行业如何变化都能保持成功。</p><p>聪明源于通才思维，而不是专才思维。</p><p>成为一个专家往往会让你与其他专家陷入直接竞争。把你的思想局限在那个专业的框架里，会阻止你在相互关联的领域中学习，而这些领域的学习本可以让你充满创造力。</p><p>聪明是整体性的、创造性的，且具有形而上学的特质。</p><p>那么，为了培养这种聪明才智，你能读的最好的书是什么？</p><p>能打开你思维的书。</p><p>关于整体论、创造力和形而上学的书。</p><p>艾伦·瓦茨（Alan Watts）是将普遍真理与实际应用相联系的一个极好的例子。这里有一段很长的引用，但它可能会帮你抓住要旨：</p><blockquote><p>我把这些基本观念称为神话，我使用‘神话（myth）’这个词，并不是简单地指代不真实的东西，而是在一种更有力量的意义上使用它。神话是一种意象，我们试图通过它来理解这个世界。现在，比如，神话在某种程度上就是一个隐喻。如果你想向一个对电一无所知的人解释电，你会说，好吧，你谈论一下电流（current，水流）。现在，‘current’这个词是借用于河流的。它是借用于水力学的，所以你是在用水来解释电。其实，电不是水，它的实际表现方式是不同的，但是水的行为和电的行为在某些方面是很像的，所以你用水来解释它。或者如果你是一位天文学家，你想向人们解释你所说的膨胀的宇宙和弯曲的空间是什么意思，你会说，‘好吧，这就像你有一个黑色的气球，黑色的气球上面有白色的圆点，那些圆点代表星系，当你把气球吹大时，所有的圆点都会均匀地越离越远。’但你使用的是一个类比——宇宙其实并不是一个上面有白点的黑气球。</p></blockquote><p>这，我的朋友们，就是聪明。</p><h3 id="我百读不厌的7本书" tabindex="-1">我百读不厌的7本书 <a class="header-anchor" href="#我百读不厌的7本书" aria-label="Permalink to &quot;我百读不厌的7本书&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>我以前常常听着艾伦·瓦茨的演讲入睡。</p><p>（我可能应该重新捡起这个习惯了）。</p><p>我几乎能实实在在地<em>感觉</em>到我的思维在打开。我能感觉到我的想法能够走向新的道路。我开始能够理解我以前不明白的事情，但这正是像上面瓦茨在引语中所说的那种隐喻的意义上的理解。</p><p>顺便说一句，这正是为什么我的邮件通讯会写这么长。我不在乎每天把你的思维局限在一个很小的知识点上。我想通过展示相互关联的思想融合，来帮助你体验那种改变了我生活的、思维扩张的感觉（这也是我们打造 Kortex 的另一个原因，为了帮助其他人以这种方式写作）。</p><p><img src="'+n+'" alt=""></p><p><img src="'+h+'" alt=""></p><p>那是我们目前作者训练营<em>第0周</em>的一个例子。</p><p>有几本书我经常重读。</p><p>每次读它们，我都能发现新的东西，并且我对生活的理解也会加深。</p><p>我按照我认为你能产生最多联系的顺序列出了它们。我专门把这些书列进去，是因为如果你读完它们，你的大脑就会因为多巴胺而兴奋起来。</p><ol><li><strong>《不可能的艺术》（The Art Of Impossible），史蒂芬·科特勒（Steven Kotler）著</strong> —— 一本关于如何实现不可能的实用科学著作。</li><li><strong>《心流》（Flow），米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）著</strong> —— 为了理解如何在生活中保持快乐。</li><li><strong>《万物简史》（A Brief History Of Everything），肯·威尔伯（Ken Wilber）著</strong> —— 以整体的方式来理解这个世界。</li><li><strong>《觉知》（Awareness），安东尼·德·梅勒（Anthony De Mello）著</strong> —— 一系列令人耳目一新且幽默风趣的讲座，帮助你不要把生活看得太严肃。</li><li><strong>《成为超自然》（Becoming Supernatural），乔·迪斯彭扎（Joe Dispenza）著</strong> —— 可能带有伪科学色彩，但其教导依然很有影响力，教你通过打破熟悉和已知事物的重复循环来改变生活。</li><li><strong>《秘典》（The Kybalion），三位入门者（The Three Initiates）著</strong> —— 赫尔墨斯哲学和现实模式的入门书籍（有人说这不是一本了解赫尔墨斯主义的好书，但我挺喜欢它的）。</li><li><strong>《卓越男人的修练》（The Way Of The Superior Man），大卫·戴达（David Deida）著</strong> —— 肯·威尔伯的一位学生写的关于男性与女性动力学以及精神成长的书。</li></ol><p>没有这些书，我的生活将会完全不同。</p><p>我自己的书，<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》</a>（The Art Of Focus），在某种程度上是所有这些书的综合，同时将其与创造性工作和互联网联系起来，以过上有意义的生活。</p><p>如果你读过我的书，觉得内容太密集难懂，我会强烈建议你通读上面列出的其他书。</p><h2 id="第三部分-如何阅读" tabindex="-1">第三部分）如何阅读 <a class="header-anchor" href="#第三部分-如何阅读" aria-label="Permalink to &quot;第三部分）如何阅读&quot;">​</a></h2><p>以下是《深度工作》（Deep Work）的作者卡尔·纽波特（Cal Newport）如何做到每个月读5本书的：</p><ol><li>选择更有趣的书。</li><li>像安排锻炼一样安排阅读时间。</li><li>形成一种仪式，让阅读更享受。</li><li>进行最后的冲刺，一口气读完一本书。</li><li>把手机上所有有趣的东西都删掉。</li></ol><p>简而言之，卡尔是一位排除生活干扰的专家，他腾出空间来做那些他认为有意义、重要且有趣的事情。</p><p>以下是我个人用来确保维持阅读习惯的方法。</p><h3 id="_1-寻觅一两个新点子-然后把书放下。" tabindex="-1">1) 寻觅一两个新点子，然后把书放下。 <a class="header-anchor" href="#_1-寻觅一两个新点子-然后把书放下。" aria-label="Permalink to &quot;1) 寻觅一两个新点子，然后把书放下。&quot;">​</a></h3><p>大多数书只要读完前2-3章就能理解个大概。</p><p>书籍通常以宏观概述开篇，然后深入探讨技术细节。</p><p>如果你正在寻找一个可供实验的过程，从而在生活中获得某种特定的结果，那就把整本书读完。</p><p>如果你像我一样，或者像我的受众里的创作者/作者一样，工作围绕着新颖视角和宏大理念展开，那么一旦你找到那个能向你的大脑喷射多巴胺和兴奋感的“金点子”，我允许你停止阅读。</p><h3 id="_2-去散步并听书。" tabindex="-1">2) 去散步并听书。 <a class="header-anchor" href="#_2-去散步并听书。" aria-label="Permalink to &quot;2) 去散步并听书。&quot;">​</a></h3><p>是的，你懂的，我喜欢散步。</p><p>我把它们当作创造力时间块（与流行的生产力时间块截然相反）。</p><p>作为一名创意或知识工作者，你生产力时间块的价值，完全取决于你用来产出成果的想法有多好。</p><p>去散步能让你远离家里的干扰。</p><p>而且，我确信有科学依据表明，活动身体能让你的大脑更容易接受新想法。</p><h3 id="_3-轮换不同主题和类型以进行模式识别。" tabindex="-1">3) 轮换不同主题和类型以进行模式识别。 <a class="header-anchor" href="#_3-轮换不同主题和类型以进行模式识别。" aria-label="Permalink to &quot;3) 轮换不同主题和类型以进行模式识别。&quot;">​</a></h3><p>我经常同时读3本书。</p><p>一本纸质书，一本Kindle电子书，一本有声书。</p><p>有时我会听我正在阅读的同一本书的有声版。</p><p>这让我的脑海中能积累一系列宏大理念，它们最终会产生新颖的联系，从而让我有内容可写。</p><h3 id="_4-让书无处不在。" tabindex="-1">4) 让书无处不在。 <a class="header-anchor" href="#_4-让书无处不在。" aria-label="Permalink to &quot;4) 让书无处不在。&quot;">​</a></h3><p>拥抱这种混乱的创意生活方式。</p><p>把书放在你的书桌上、厨房操作台上、床头柜上、马桶边。</p><p>到处放些便利贴以防有想法冒出来，或者在今年晚些时候 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex 捕获</a> 上线后使用它（我这么频繁地用Kortex吊你们胃口，抱歉但我并不觉得抱歉）。</p><p>目标是让阅读变得比你的手机更有趣。</p><h3 id="_5-打造一个你热爱的阅读空间。" tabindex="-1">5) 打造一个你热爱的阅读空间。 <a class="header-anchor" href="#_5-打造一个你热爱的阅读空间。" aria-label="Permalink to &quot;5) 打造一个你热爱的阅读空间。&quot;">​</a></h3><p>除了长距离散步之外，我喜欢坐在一个私密、安静的地方，端着一杯好咖啡来阅读。</p><p>有朝一日，我希望能在我家里专门辟出一个房间用来阅读。里面除了书，什么都不准放。</p><p>至于现在，我就坐在自家的露台上。</p><h2 id="第4部分-写作不仅是给作家准备的" tabindex="-1">第4部分) 写作不仅是给作家准备的 <a class="header-anchor" href="#第4部分-写作不仅是给作家准备的" aria-label="Permalink to &quot;第4部分) 写作不仅是给作家准备的&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>写作 = 有条理的思考。</p><p>有条理的思考 = 有效的沟通。</p><p>沟通 = 如何从生活中获得你想要的东西。</p><p>阅读只能带你走这么远。</p><p>我们都遇见过那种满脑子想法，却从未打造出任何值得追随、使用或从中受益的东西的人。</p><p>你为什么阅读？</p><p>为什么这封信你一路读到了这里？</p><p>对一些人来说，是为了地位。你想标榜自己读了很多书，让你显得在生活中有点正事干，以此来给别人留下深刻印象。</p><p>这没问题，但如果你从未 <em>创造</em> 过任何有益于人类的东西，这种对地位的追求只会让你感到空虚。</p><p>你不需要自诩为作家才可以开始写作。</p><p>你，作为一个人类，<em>就是</em> 一个创作者。你从获得的知识中构建工具和解决方案，以此来生存和进化。这与动物截然不同。</p><p>你其实每天都在写作。这是人类体验的内在组成部分。写作是我们这个物种赖以生存的方式。我们在岩石上雕刻，在莎草纸上书写，让信息不朽，从而让其他人可以利用这些信息更快地取得进步并避开危险。没有其他物种做到过这点。写作的能力就是你的优势。</p><p>你早就在写电子邮件、短信和笔记了，好防止你的大脑因为伴随技术进步而来的海量信息陷入疯狂。</p><p>多亏了互联网，现在任何人都可以进行规模化写作、建立受众群体，并利用他们培养的任何让受众受益的技能或兴趣来谋生。</p><h3 id="在哪里写" tabindex="-1">在哪里写 <a class="header-anchor" href="#在哪里写" aria-label="Permalink to &quot;在哪里写&quot;">​</a></h3><p>当我还是个孩子的时候，我总是幻想着能写一本书。</p><p>然后，我把这个念头忘了整整10年，好让自己能够顺着别人告诉我的唯一一条路生存下去：上学、找工作、退休。我对此并不顺心，但这是我唯一知道的事。</p><p>许多人告诉我他们想写一本书，或者他们纯粹梦想着能在社会为你规划的传统路线之外做点什么。</p><p>问题在于，大多数人确实有这些梦想，但他们认为只要决定去做的瞬间，事情自然就会成了。好吧，也许他们并没有这么想，但他们的表现就像是这么认为的。</p><p>他们没有意识到，要写一本书，你需要有海量的想法去打磨。</p><p>他们没有意识到，要做你自己的事，你需要有人愿意为此向你付钱。</p><p>这两者都需要你坐在键盘前，以特定的顺序敲下文字，才能达到那种结果。</p><p>对于大多数人来说，实现这一目标最实惠也最容易上手的途径——感谢技术，因为这只在进化的这个节点上才成为可能——就是社交媒体。</p><p>你写短帖和主题帖来吸引受众。</p><p>然后，你开始写篇幅更长的新闻通讯来培育这些受众。</p><p>在你不知不觉中，你已经写了成千上万篇帖子和几百篇新闻通讯，它们 <em>转化成</em> 了一本书，或一群热爱你所做之事的忠实受众。</p><p>所以，通过在社交媒体上写作，你开始向着梦想迈进。</p><p>这不是唯一的路，但这是一条每个人——没错，每个人——都能走的路。</p><p>社交媒体赋予了人类巨大的力量，但他们却把它误当成了娱乐、享乐和消遣的工具。</p><h3 id="写什么" tabindex="-1">写什么 <a class="header-anchor" href="#写什么" aria-label="Permalink to &quot;写什么&quot;">​</a></h3><p>你不需要选择一个细分领域。</p><p><a href="/letters/the-most-profitable-niche-is-you-how-to-create-your-niche">你就是细分领域。</a></p><p>你独特的人生目标框定了你如何解读和关注周围的信息。</p><p>当你阅读时，你注意到的想法组合，与另一个读同一本书的人完全不同。</p><p>你的大脑会自动告诉你，哪些想法对你的未来很重要。</p><p>所以，你要写下那些帮助你实现目标的想法。</p><p>你写下你的目标以及你是如何实现它们的，从而吸引到有同样目标的人。那就是你的细分领域。那些想要进步的人。</p><p>单是这种组合就让你独一无二。</p><p>别再纠结你的目标受众是谁，或者该进入哪个细分领域了。</p><p>开始关注这两者的本质。</p><p>你是在试图吸引你能帮助的人。</p><p>你能帮助那些与你有相同目标的人。</p><p>你写下那些观点、见解和建议，给人们提供实现目标的火力。</p><p>然后，如果你想卖产品或服务（就像我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学 (Digital Economics)</a> 里教的那样），你就会拥有一群想要从你这里买单的受众，而且到了那个时候，很可能他们会主动让你去创造点什么出来卖。</p><h3 id="怎么写" tabindex="-1">怎么写 <a class="header-anchor" href="#怎么写" aria-label="Permalink to &quot;怎么写&quot;">​</a></h3><p>Naval (纳瓦尔) 把推特当作他的记笔记平台。</p><p>他读一本书，发现一个想法，然后 <em>从他自己的视角</em> 把它分享给受众。</p><p>他觉得这个想法很有影响力，所以他与世界分享，并让其他同样觉得有影响力的人来关注他。</p><p>事情可以就是这么简单。</p><p>搜寻想法，分享想法。</p><p>一种美丽的信息流，既能使你自己受益，也能惠及他人。</p><p>除此之外，有影响力的写作在于改变行为。</p><p>你的工作是写出能说服人们做出更好决定的论点，而不是去强迫或欺骗。这就是你为人类做贡献的方式。</p><p>思考这个问题的最佳方式，就是把写作当成是写给你自己的。</p><p>我所有的帖子和新闻通讯都是写给我的。</p><p>我的个人主页就是我公开的日记。</p><p>我说服自己做出更好的决定（比如多阅读），以便让这些想法固化为我身份的一部分。一个更好、更全面的身份。</p><p>如果你陷入了写那些诸如打炮或赚快钱等肤浅而短视的话题，并且从不超越这些去深入思考，你也会变成那样……肤浅而短视。我不是说别写这些东西，我是说要通过教育和经验，在它们背后培养一种有深度和意义的哲学。</p><p>写给过去的自己，鼓励他们改进。展示给他们该怎么做。</p><p>写给现在的自己，为他们设定程序去表现得更好。</p><p><em>以</em> 未来自己的身份写作，给现在的自己提建议。</p><p>当你阅读时，记下那些令你印象深刻的想法。记下“顿悟”时刻。记下那些你可以亲身实验并化为己用的可执行建议。</p><p>还要记住，你不仅仅是在分享你从书本中获得的想法。</p><p>通常，你利用那些想法去实现你的目标，并分享帮助你实现目标的心态与技能。</p><p>写作不必那么复杂。你不需要我的 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时作者 (2 Hour Writer)</a> 课程就能参与到试错的过程中。</p><p>如果你确实想要教育指导和模板来加快这个过程，那当然，买下它。话说到这份上，我都觉得有点义务推销一下了。毕竟我们在谈论写作嘛。</p><p>但是，写作也可以仅仅只是写作。</p><p>你已经在做了。</p><p>只是要开始用一种能带来杠杆和更好未来的方式去做。</p><p>感谢你的阅读。</p><p>– Dan</p><hr><p><a href="/en/letters/reading-change-your-life-with-one-simple-habit">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',292))])}const N=m(g,[["render",k]]);export{D as __pageData,N as default};
